def comps(cells):
    cells=set(cells); out=[]
    while cells:
        c=cells.pop(); stack=[c]; comp=[c]
        while stack:
            r,cc=stack.pop()
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    p=(r+dr,cc+dc)
                    if p in cells: cells.remove(p); stack.append(p); comp.append(p)
        out.append(sorted(comp))
    return out
